package com.practiq;
import static org.junit.jupiter.api.Assertions.*; import com.practiq.common.*; import com.practiq.service.*; import java.time.*; import java.util.*; import org.junit.jupiter.api.Test;
class CoreRulesTest { @Test void cursorRoundTrip(){assertEquals(0,PageSupport.cursor(""));assertEquals(20,PageSupport.cursor(PageSupport.next(0,20)));assertThrows(ApiException.class,()->PageSupport.cursor("bad"));}@Test void trialGrantsPro(){var s=new MembershipService();assertEquals("pro",s.effective("free",OffsetDateTime.now().plusDays(1)));assertEquals("free",s.effective("free",OffsetDateTime.now().minusDays(1)));}@Test void gradesChoiceAndBlanks(){var s=new GradingService();assertTrue(s.grade("choice",Map.of("selected",List.of("A","B")),Map.of("selected",List.of("B","A"))));assertTrue(s.grade("fill_blank",Map.of("value",List.of("Paris","France")),Map.of("value",List.of(" paris ","france","x"))));assertNull(s.grade("short_answer",Map.of(),Map.of()));}}
